<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>StockControl</title><link rel="stylesheet" href="css/style.css"></head><body><header><div><strong>▣ StockControl</strong><small>Controle de estoque · Projeto Integrador</small></div><button id="logout" hidden>Sair</button></header><main><section id="notice" role="status"></section><section id="setup" class="card" hidden><h1>Primeiro acesso</h1><p>Crie o primeiro usuário administrador (somente em ambiente local).</p><form id="setupForm"><label>Nome<input name="nome" required maxlength="150"></label><label>E-mail<input name="email" type="email" required></label><label>Senha (mínimo 10 caracteres)<input name="senha" type="password" minlength="10" required></label><button>Criar usuário</button></form></section><section id="login" class="card" hidden><h1>Entrar</h1><form id="loginForm"><label>E-mail<input name="email" type="email" required></label><label>Senha<input name="senha" type="password" required></label><button>Entrar</button></form></section><section id="app" hidden><nav><button data-tab="dashboard">Resumo</button><button data-tab="produtos">Produtos</button><button data-tab="fornecedores">Fornecedores</button><button data-tab="categorias">Categorias</button><button data-tab="movimentacoes">Movimentações</button><button data-tab="historico">Histórico</button></nav><section id="dashboard" class="panel"><h1>Visão geral</h1><div id="stats" class="stats"></div><h2>Estoque mínimo</h2><div id="alertas"></div></section><section id="produtos" class="panel" hidden><h1>Produtos</h1><form id="produtoForm" class="grid card"><label>Nome<input name="nome" required></label><label>SKU<input name="sku" required></label><label>Categoria<select name="categoria_id" required></select></label><label>Fornecedor<select name="fornecedor_id" required></select></label><label>Estoque mínimo<input name="estoque_minimo" type="number" min="0" value="5" required></label><label>Preço de custo<input name="preco_custo" type="number" min="0" step="0.01" value="0" required></label><label class="wide">Descrição<input name="descricao"></label><input type="hidden" name="id" value=""><button id="salvarProduto">Cadastrar produto</button><button id="cancelarEdicao" type="button" hidden>Cancelar edição</button></form><div id="tabelaProdutos"></div></section><section id="fornecedores" class="panel" hidden><h1>Fornecedores</h1><form id="fornecedorForm" class="grid card"><input type="hidden" name="id"><label>Nome<input name="nome" required maxlength="150"></label><label>CNPJ (14 dígitos, opcional)<input name="cnpj" inputmode="numeric" maxlength="18"></label><label>Telefone<input name="telefone" maxlength="20"></label><label>E-mail<input name="email" type="email" maxlength="150"></label><label class="wide">Endereço<input name="endereco" maxlength="255"></label><button id="salvarFornecedor">Cadastrar fornecedor</button><button id="cancelarFornecedor" type="button" hidden>Cancelar edição</button></form><div id="tabelaFornecedores"></div></section><section id="categorias" class="panel" hidden><h1>Categorias</h1><form id="categoriaForm" class="grid card"><label>Nome<input name="nome" required maxlength="100"></label><label>Descrição<input name="descricao" maxlength="255"></label><button>Cadastrar categoria</button></form><div id="tabelaCategorias"></div></section><section id="movimentacoes" class="panel" hidden><h1>Registrar movimentação</h1><form id="movForm" class="grid card"><label>Produto<select name="produto_id" required></select></label><label>Tipo<select name="tipo"><option value="ENTRADA">Entrada</option><option value="SAIDA">Saída</option></select></label><label>Quantidade<input name="quantidade" type="number" min="1" required></label><label>Observação<input name="observacao"></label><button>Registrar</button></form></section><section id="historico" class="panel" hidden><h1>Histórico das últimas 100 movimentações</h1><div id="tabelaHistorico"></div></section></section></main><footer>StockControl · UCEFF · 2026/2</footer><script src="js/app.js"></script></body></html>
